/**
 * 解决页面刷新后内容不可见的问题
 */

(function() {
    'use strict';
    
    // 确保内容区域可见的函数
    function ensureContentVisible() {
        const safearea = document.getElementById('safearea');
        if (safearea) {
            safearea.style.display = 'block';
            safearea.style.opacity = '1';
            safearea.style.visibility = 'visible';
        }
        
        // 确保其他主要容器也可见
        const containers = ['#l_main', '#pjax-container', '.l_main'];
        containers.forEach(selector => {
            const element = document.querySelector(selector);
            if (element) {
                element.style.display = 'block';
                element.style.opacity = '1';
                element.style.visibility = 'visible';
            }
        });
    }
    
    // 立即执行一次
    ensureContentVisible();
    
    // 多重初始化 - 确保在各种情况下都能正确初始化
    // 1. DOM 加载完成
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', ensureContentVisible);
    } else {
        ensureContentVisible();
    }
    
    // 2. 窗口加载完成（处理异步内容）
    window.addEventListener('load', ensureContentVisible);
    
    // 3. PJAX 页面加载完成（如果使用 PJAX）
    document.addEventListener('pjax:complete', ensureContentVisible);
    
    // 4. 延迟初始化（确保动态内容加载完成）
    setTimeout(ensureContentVisible, 500);
    setTimeout(ensureContentVisible, 1000);
    
})();

